// <auto-generated/>
#nullable enable

using System;
using System.Globalization;
using System.Text;
using Haitch.Roslyn.Models;
using Haitch.Roslyn.Types;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace Haitch.Roslyn.Writing;

/// <summary>
/// Renders the slice 3 models (<see cref="TypeModel"/>, <see cref="MethodModel"/>, ...) as C# source
/// text through a <see cref="SourceWriter"/>. Only declarations are rendered; method bodies and
/// expression builders are out of scope here.
/// </summary>
internal static class SourceWriterExtensions
{
    /// <summary>
    /// Writes the standard generated-file header: <c>// &lt;auto-generated/&gt;</c> followed by
    /// <c>#nullable enable</c> and a blank line.
    /// </summary>
    public static SourceWriter WriteAutoGeneratedHeader(this SourceWriter writer)
    {
        writer.WriteLine("// <auto-generated/>");
        writer.WriteLine("#nullable enable");
        writer.WriteLine();

        return writer;
    }

    /// <summary>
    /// Writes a file-scoped namespace declaration followed by a blank line. Writes nothing when
    /// <paramref name="namespaceName"/> is <see langword="null"/> (the global namespace).
    /// </summary>
    public static SourceWriter WriteNamespace(this SourceWriter writer, string? namespaceName)
    {
        if (namespaceName is not null)
        {
            writer.WriteLine($"namespace {namespaceName};");
            writer.WriteLine();
        }

        return writer;
    }

    /// <summary>
    /// Writes <paramref name="type"/>'s partial declaration wrapped in the partial declarations of
    /// its containing types (outermost first), opening one block per level. Disposing the returned
    /// scope closes every opened block, innermost first.
    /// </summary>
    /// <remarks>
    /// Only <c>readonly</c>/<c>ref</c> (required on every partial struct declaration), <c>partial</c>,
    /// the type kind, the name, and type parameters (with constraints) are written; accessibility and
    /// <c>static</c>/<c>abstract</c>/<c>sealed</c> are never echoed back onto a partial declaration.
    /// </remarks>
    /// <param name="writer">The writer to write to.</param>
    /// <param name="type">The type to declare.</param>
    /// <param name="baseTypes">
    /// Extra base types written on the innermost declaration only, never on its containing types, and
    /// not validated: the compiler reports conflicts with the other declarations of the type.
    /// </param>
    public static TypeDeclarationScope WriteTypeDeclaration(
        this SourceWriter writer,
        TypeModel type,
        EquatableArray<TypeRef> baseTypes = default
    )
    {
        if (type.IsFileLocal)
        {
            throw new ArgumentException(
                "Cannot write a partial declaration for a file-local type: file-local types cannot be split "
                    + "across a generated partial declaration in a different file.",
                nameof(type));
        }

        var scopes = new SourceWriter.BlockScope[type.ContainingTypes.Count + 1];

        for (var i = 0; i < type.ContainingTypes.Count; i++)
        {
            ContainingTypeModel containingType = type.ContainingTypes[i];

            WriteTypeDeclarationLine(
                writer,
                containingType.IsReadOnly,
                containingType.IsRefLikeType,
                containingType.Kind,
                containingType.Name,
                containingType.TypeParameters);

            scopes[i] = writer.Block();
        }

        WriteTypeDeclarationLine(
            writer,
            type.IsReadOnly,
            type.IsRefLikeType,
            type.Kind,
            type.Name,
            type.TypeParameters,
            baseTypes
        );
        scopes[type.ContainingTypes.Count] = writer.Block();

        return new TypeDeclarationScope(scopes);
    }

    /// <summary>
    /// Writes the header of a brand-new, non-partial type and opens its block. Throws
    /// <see cref="ArgumentException"/> before writing anything for an illegal modifier combination.
    /// </summary>
    /// <remarks>
    /// Always opens a <c>{ }</c> body, including for a record with
    /// <see cref="NewTypeModel.PrimaryConstructorParameters"/>, which is written as
    /// <c>record Person(string Name) { }</c>. Use <see cref="WriteBodylessNewTypeDeclaration"/> for the
    /// <c>;</c> form.
    /// </remarks>
    public static SourceWriter.BlockScope WriteNewTypeDeclaration(this SourceWriter writer, NewTypeModel type)
    {
        writer.WriteLine(RenderNewTypeHeader(type));

        return writer.Block();
    }

    /// <summary>
    /// Writes a complete bodyless positional record such as <c>record Person(string Name, int Age);</c>.
    /// Throws <see cref="ArgumentException"/> before writing anything unless the kind is a record class or
    /// record struct with non-null <see cref="NewTypeModel.PrimaryConstructorParameters"/>, or when the
    /// model is otherwise illegal.
    /// </summary>
    /// <remarks>
    /// Nothing is opened, so no members can be written inside the type afterwards; use
    /// <see cref="WriteNewTypeDeclaration"/> when the type needs a body.
    /// </remarks>
    public static void WriteBodylessNewTypeDeclaration(this SourceWriter writer, NewTypeModel type)
    {
        var header = RenderNewTypeHeader(type);

        if (type.Kind is not (TypeDeclarationKind.RecordClass or TypeDeclarationKind.RecordStruct)
            || type.PrimaryConstructorParameters is null)
        {
            throw new ArgumentException(
                $"'{type.Name}' cannot be written without a body: only a record class or record struct with primary constructor parameters can end in ';'.",
                nameof(type));
        }

        writer.WriteLine(header + ";");
    }

    private static string RenderNewTypeHeader(NewTypeModel type)
    {
        ValidateNewType(type);

        var builder = new StringBuilder();

        if (type.Accessibility == Accessibility.NotApplicable)
        {
            if (type.IsFileLocal)
            {
                builder.Append("file ");
            }
        }
        else
        {
            AppendAccessibility(builder, type.Accessibility);
        }

        if (type.IsStatic)
        {
            builder.Append("static ");
        }
        else if (type.IsAbstract)
        {
            builder.Append("abstract ");
        }
        else if (type.IsSealed)
        {
            builder.Append("sealed ");
        }

        if (type.IsClosed)
        {
            builder.Append("closed ");
        }

        if (type.IsReadOnly)
        {
            builder.Append("readonly ");
        }

        if (type.IsRefLikeType)
        {
            builder.Append("ref ");
        }

        if (type.IsPartial)
        {
            builder.Append("partial ");
        }

        builder.Append(KindKeyword(type.Kind)).Append(' ').Append(EscapeKeyword(type.Name));
        AppendTypeParameterList(builder, type.TypeParameters);

        if (type.PrimaryConstructorParameters is { } primaryConstructorParameters)
        {
            AppendParameterList(builder, primaryConstructorParameters, isExtensionMethod: false);
        }

        if (type.UnionCaseTypes.Count > 0)
        {
            builder.Append('(');

            for (var i = 0; i < type.UnionCaseTypes.Count; i++)
            {
                builder.Append(i == 0 ? "" : ", ").Append(type.UnionCaseTypes[i]);
            }

            builder.Append(')');
        }

        AppendBaseList(builder, type.BaseTypes);
        AppendWhereClauses(builder, type.TypeParameters);

        return builder.ToString();
    }

    internal static void ValidateNewType(NewTypeModel type)
    {
        var bareName = type.Name.StartsWith("@", StringComparison.Ordinal) ? type.Name.Substring(1) : type.Name;

        if (!SyntaxFacts.IsValidIdentifier(bareName))
        {
            throw new ArgumentException($"'{type.Name}' is not a valid type name.", nameof(type));
        }

        if (type.IsFileLocal && type.Accessibility != Accessibility.NotApplicable)
        {
            throw new ArgumentException(
                $"'{type.Name}' is file-local, which cannot be combined with an accessibility.",
                nameof(type));
        }

        var isClassLike = type.Kind is TypeDeclarationKind.Class or TypeDeclarationKind.RecordClass;

        if (type.PrimaryConstructorParameters is not null
            && (type.IsStatic || type.Kind is TypeDeclarationKind.Interface or TypeDeclarationKind.Union))
        {
            throw new ArgumentException(
                $"'{type.Name}' is a {(type.IsStatic ? "static class" : type.Kind.ToString())}, which cannot have a primary constructor.",
                nameof(type));
        }

        if (type.IsStatic && (type.Kind != TypeDeclarationKind.Class || type.IsAbstract || type.IsSealed || type.BaseTypes.Count > 0))
        {
            throw new ArgumentException(
                $"'{type.Name}' is static, which requires a plain class and excludes abstract, sealed and base types.",
                nameof(type));
        }

        if (type.IsAbstract && type.IsSealed)
        {
            throw new ArgumentException($"'{type.Name}' cannot be both abstract and sealed.", nameof(type));
        }

        if (!isClassLike && (type.IsStatic || type.IsAbstract || type.IsSealed))
        {
            throw new ArgumentException(
                $"'{type.Name}' is a {type.Kind}, which cannot be static, abstract or sealed.",
                nameof(type));
        }

        if (type.IsClosed && !isClassLike)
        {
            throw new ArgumentException(
                $"'{type.Name}' is a {type.Kind}, which cannot be closed; only a class or record can.",
                nameof(type));
        }

        if (type.IsClosed && (type.IsAbstract || type.IsSealed || type.IsStatic))
        {
            throw new ArgumentException(
                $"'{type.Name}' is closed, which cannot be combined with abstract, sealed or static.",
                nameof(type));
        }

        if (type.Kind == TypeDeclarationKind.Union)
        {
            if (type.UnionCaseTypes.Count == 0 && !type.IsPartial)
            {
                throw new ArgumentException(
                    $"'{type.Name}' is a union without case types; only a partial union part may omit the case list.",
                    nameof(type));
            }

            if (type.IsRefLikeType)
            {
                throw new ArgumentException($"'{type.Name}' is a union, which cannot be ref.", nameof(type));
            }

            for (var i = 0; i < type.UnionCaseTypes.Count; i++)
            {
                if (string.IsNullOrWhiteSpace(type.UnionCaseTypes[i]))
                {
                    throw new ArgumentException(
                        $"'{type.Name}' has an empty union case type.",
                        nameof(type));
                }
            }
        }
        else if (type.UnionCaseTypes.Count > 0)
        {
            throw new ArgumentException(
                $"'{type.Name}' is a {type.Kind}, which cannot have union case types.",
                nameof(type));
        }

        var canBeReadOnlyOrRef =
            type.Kind is TypeDeclarationKind.Struct or TypeDeclarationKind.RecordStruct or TypeDeclarationKind.Union;

        if (!canBeReadOnlyOrRef && (type.IsReadOnly || type.IsRefLikeType))
        {
            throw new ArgumentException(
                $"'{type.Name}' is a {type.Kind}, which cannot be readonly or ref.",
                nameof(type));
        }

        if (type.IsRefLikeType && type.Kind == TypeDeclarationKind.RecordStruct)
        {
            throw new ArgumentException($"'{type.Name}' is a record struct, which cannot be ref.", nameof(type));
        }

        for (var i = 0; i < type.BaseTypes.Count; i++)
        {
            var isInterface = type.BaseTypes[i].TypeKind == TypeKind.Interface;

            if (!isInterface && (!isClassLike || i != 0))
            {
                throw new ArgumentException(
                    $"'{type.BaseTypes[i].FullyQualifiedName}' is not an interface; only a class or record may have a base class, and it must be the only one and listed first.",
                    nameof(type));
            }
        }

        // Only interfaces (and delegates, which are not a NewType kind) can declare variant type parameters.
        if (type.Kind != TypeDeclarationKind.Interface)
        {
            for (var i = 0; i < type.TypeParameters.Count; i++)
            {
                if (type.TypeParameters[i].Variance != VarianceKind.None)
                {
                    throw new ArgumentException(
                        $"'{type.Name}' is a {type.Kind}, which cannot have a variant type parameter ('{type.TypeParameters[i].Name}').",
                        nameof(type));
                }
            }
        }
    }

    /// <summary>
    /// Writes a method signature from <paramref name="method"/>, terminated with <c>;</c>. Never
    /// writes a body: this is the shape a generator uses for the defining declaration of a partial
    /// method, an abstract member, or an interface member.
    /// </summary>
    public static SourceWriter WriteMethodSignature(this SourceWriter writer, MethodModel method)
    {
        writer.WriteLine(RenderMethodHeader(method) + ";");

        return writer;
    }

    /// <summary>
    /// Renders the text <see cref="WriteMethodSignature"/> writes without the terminating <c>;</c>, for
    /// callers that follow it with a body and want rendering to fail before anything is written.
    /// </summary>
    internal static string RenderMethodHeader(MethodModel method)
    {
        var builder = new StringBuilder();
        bool isExplicitInterfaceImplementation = method.ExplicitInterfaceMemberName is not null;

        // Only interface and delegate type parameters can be variant; 'void M<in T>()' does not compile.
        for (var i = 0; i < method.TypeParameters.Count; i++)
        {
            if (method.TypeParameters[i].Variance != VarianceKind.None)
            {
                throw new ArgumentException(
                    $"Method '{method.Name}' cannot have a variant type parameter ('{method.TypeParameters[i].Name}').",
                    nameof(method));
            }
        }

        // An explicit implementation takes no accessibility and no inheritance modifier, but still
        // carries static (static abstract members), extern, async and readonly.
        if (!isExplicitInterfaceImplementation && method.HasExplicitAccessibility)
        {
            AppendAccessibility(builder, method.Accessibility);
        }

        if (method.IsStatic)
        {
            builder.Append("static ");
        }

        if (method.IsExtern)
        {
            builder.Append("extern ");
        }

        if (!isExplicitInterfaceImplementation)
        {
            if (method.IsAbstract)
            {
                builder.Append("abstract ");
            }
            else if (method.IsSealed && method.IsOverride)
            {
                builder.Append("sealed override ");
            }
            else if (method.IsOverride)
            {
                builder.Append("override ");
            }
            else if (method.IsVirtual)
            {
                builder.Append("virtual ");
            }
        }

        if (method.IsAsync)
        {
            builder.Append("async ");
        }

        if (method.IsReadOnly)
        {
            builder.Append("readonly ");
        }

        if (method.IsPartialDefinition)
        {
            builder.Append("partial ");
        }

        AppendReturnRefKind(builder, method.ReturnRefKind);
        builder.Append(method.ReturnType.FullyQualifiedName).Append(' ');

        if (isExplicitInterfaceImplementation)
        {
            builder.Append(method.ExplicitInterface!.FullyQualifiedName).Append('.').Append(method.ExplicitInterfaceMemberName);
        }
        else
        {
            builder.Append(method.Name);
        }

        AppendTypeParameterList(builder, method.TypeParameters);
        AppendParameterList(builder, method.Parameters, method.IsExtensionMethod);

        // An explicit interface implementation or an override inherits its constraints from the
        // interface/base member; writing them again is a compile error (CS0460).
        if (!isExplicitInterfaceImplementation && !method.IsOverride)
        {
            AppendWhereClauses(builder, method.TypeParameters);
        }

        return builder.ToString();
    }

    /// <summary>
    /// Writes <paramref name="attribute"/> as one <c>[global::...(...)]</c> line. Throws
    /// <see cref="ArgumentException"/> before writing anything when an argument is an error constant.
    /// </summary>
    public static SourceWriter WriteAttribute(this SourceWriter writer, AttributeModel attribute)
    {
        writer.WriteLine(RenderAttribute(attribute));

        return writer;
    }

    /// <summary>
    /// Writes one attribute line per entry of <paramref name="attributes"/>, in order, and nothing for an
    /// empty array. Every attribute is rendered before the first line is written, so a failure leaves the
    /// writer untouched.
    /// </summary>
    public static SourceWriter WriteAttributes(this SourceWriter writer, EquatableArray<AttributeModel> attributes)
    {
        var lines = new string[attributes.Count];

        for (var i = 0; i < lines.Length; i++)
        {
            lines[i] = RenderAttribute(attributes[i]);
        }

        for (var i = 0; i < lines.Length; i++)
        {
            writer.WriteLine(lines[i]);
        }

        return writer;
    }

    // The attribute type is written fully qualified with its "Attribute" suffix, which always resolves.
    internal static string RenderAttribute(AttributeModel attribute)
    {
        var builder = new StringBuilder("[").Append(attribute.AttributeType.FullyQualifiedName);

        if (attribute.ConstructorArguments.Count > 0 || attribute.NamedArguments.Count > 0)
        {
            builder.Append('(');
            var first = true;

            for (var i = 0; i < attribute.ConstructorArguments.Count; i++)
            {
                if (!first)
                {
                    builder.Append(", ");
                }

                builder.Append(RenderConstant(attribute.ConstructorArguments[i], forAttribute: true));
                first = false;
            }

            for (var i = 0; i < attribute.NamedArguments.Count; i++)
            {
                if (!first)
                {
                    builder.Append(", ");
                }

                NamedArgument named = attribute.NamedArguments[i];
                builder.Append(EscapeKeyword(named.Name)).Append(" = ").Append(RenderConstant(named.Value, forAttribute: true));
                first = false;
            }

            builder.Append(')');
        }

        return builder.Append(']').ToString();
    }

    // A const field is implicitly static and takes its value from the model, so `static` is never written
    // for it and an explicit initializer would contradict ConstantValue.
    internal static string RenderField(FieldModel field, string? initializer)
    {
        if (initializer is not null && string.IsNullOrWhiteSpace(initializer))
        {
            throw new ArgumentException("The initializer must not be blank.", nameof(initializer));
        }

        var builder = new StringBuilder();
        AppendAccessibility(builder, field.Accessibility);

        if (field.IsConst)
        {
            if (initializer is not null)
            {
                throw new ArgumentException(
                    $"'{field.Name}' is const; its value comes from ConstantValue, not an initializer.",
                    nameof(initializer));
            }

            if (field.ConstantValue is null)
            {
                throw new ArgumentException($"'{field.Name}' is const but has no ConstantValue.", nameof(field));
            }

            builder.Append("const ");
        }
        else
        {
            if (field.IsStatic)
            {
                builder.Append("static ");
            }

            if (field.IsReadOnly)
            {
                builder.Append("readonly ");
            }

            if (field.IsRequired)
            {
                builder.Append("required ");
            }

            if (field.IsVolatile)
            {
                builder.Append("volatile ");
            }
        }

        builder.Append(field.Type.FullyQualifiedName).Append(' ').Append(field.Name);

        if (field.IsConst)
        {
            builder.Append(" = ").Append(RenderConstant(field.ConstantValue!));
        }
        else if (initializer is not null)
        {
            builder.Append(" = ").Append(initializer);
        }

        return builder.Append(';').ToString();
    }

    // Only field-like events can be written as a single line: accessor bodies are not modelled, and an
    // explicit implementation cannot carry accessibility or a plain name.
    internal static string RenderEvent(EventModel evt)
    {
        if (!evt.IsFieldLike)
        {
            throw new ArgumentException(
                $"'{evt.Name}' has custom accessors; only field-like events can be written.",
                nameof(evt));
        }

        if (evt.ExplicitInterface is not null)
        {
            throw new ArgumentException(
                $"'{evt.Name}' is an explicit interface implementation, which cannot be written as a field-like event.",
                nameof(evt));
        }

        var builder = new StringBuilder();
        AppendAccessibility(builder, evt.Accessibility);

        if (evt.IsStatic)
        {
            builder.Append("static ");
        }

        if (evt.IsAbstract && evt.IsOverride)
        {
            builder.Append("abstract override ");
        }
        else if (evt.IsSealed && evt.IsOverride)
        {
            builder.Append("sealed override ");
        }
        else if (evt.IsOverride)
        {
            builder.Append("override ");
        }
        else if (evt.IsSealed)
        {
            builder.Append("sealed ");
        }
        else if (evt.IsAbstract)
        {
            builder.Append("abstract ");
        }
        else if (evt.IsVirtual)
        {
            builder.Append("virtual ");
        }

        return builder.Append("event ").Append(evt.Type.FullyQualifiedName).Append(' ').Append(evt.Name).Append(';').ToString();
    }

    // Everything up to the accessor list, so accessor scopes (10.5) can share the header.
    internal static string RenderPropertyHeader(PropertyModel property)
    {
        var builder = new StringBuilder();

        if (property.HasExplicitAccessibility)
        {
            AppendAccessibility(builder, property.Accessibility);
        }

        if (property.IsStatic)
        {
            builder.Append("static ");
        }

        if (property.IsSealed && property.IsOverride)
        {
            builder.Append("sealed override ");
        }
        else if (property.IsOverride)
        {
            builder.Append("override ");
        }
        else if (property.IsSealed)
        {
            builder.Append("sealed ");
        }
        else if (property.IsVirtual)
        {
            builder.Append("virtual ");
        }

        if (property.IsRequired)
        {
            builder.Append("required ");
        }

        if (property.IsReadOnly)
        {
            builder.Append("readonly ");
        }

        if (property.IsPartial)
        {
            builder.Append("partial ");
        }

        AppendReturnRefKind(builder, property.ReturnRefKind);

        return builder.Append(property.Type.FullyQualifiedName).Append(' ').Append(property.Name).ToString();
    }

    // Accessor accessibility is written only when it narrows the property's own.
    internal static string RenderAccessorKeyword(PropertyAccessorModel accessor, Accessibility propertyAccessibility)
    {
        var builder = new StringBuilder();

        if (accessor.Accessibility != propertyAccessibility)
        {
            AppendAccessibility(builder, accessor.Accessibility);
        }

        if (accessor.IsReadOnly)
        {
            builder.Append("readonly ");
        }

        return builder
            .Append(
                accessor.Kind switch
                {
                    PropertyAccessorKind.Get => "get",
                    PropertyAccessorKind.Set => "set",
                    PropertyAccessorKind.Init => "init",
                    _ => throw new ArgumentOutOfRangeException(nameof(accessor), accessor.Kind, "Unsupported accessor kind."),
                })
            .ToString();
    }

    internal static string RenderAutoProperty(PropertyModel property)
    {
        if (property.IsAbstract)
        {
            throw new ArgumentException(
                $"'{property.Name}' is abstract (or an interface member) and cannot be an auto-property.",
                nameof(property));
        }

        if (property.ExplicitInterface is not null)
        {
            throw new ArgumentException(
                $"'{property.Name}' is an explicit implementation of '{property.ExplicitInterface.FullyQualifiedName}', which cannot be written as an auto-property.",
                nameof(property));
        }

        if (!HasGetAccessor(property))
        {
            throw new ArgumentException(
                $"'{property.Name}' has no get accessor; an auto-property requires one.",
                nameof(property));
        }

        if (property.ReturnRefKind != ReturnRefKind.None)
        {
            throw new ArgumentException(
                $"'{property.Name}' returns by ref, which cannot be written as an auto-property.",
                nameof(property));
        }

        var builder = new StringBuilder(RenderPropertyHeader(property)).Append(" { ");

        for (var i = 0; i < property.Accessors.Count; i++)
        {
            builder.Append(RenderAccessorKeyword(property.Accessors[i], property.Accessibility)).Append("; ");
        }

        return builder.Append('}').ToString();
    }

    private static bool HasGetAccessor(PropertyModel property)
    {
        for (var i = 0; i < property.Accessors.Count; i++)
        {
            if (property.Accessors[i].Kind == PropertyAccessorKind.Get)
            {
                return true;
            }
        }

        return false;
    }

    internal static void WriteTypeDeclarationLine(
        SourceWriter writer,
        bool isReadOnly,
        bool isRefLikeType,
        TypeDeclarationKind kind,
        string name,
        EquatableArray<TypeParameterModel> typeParameters,
        EquatableArray<TypeRef> baseTypes = default)
    {
        var builder = new StringBuilder();

        if (isReadOnly)
        {
            builder.Append("readonly ");
        }

        if (isRefLikeType)
        {
            builder.Append("ref ");
        }

        builder.Append("partial ").Append(KindKeyword(kind)).Append(' ').Append(name);

        AppendTypeParameterList(builder, typeParameters);
        AppendBaseList(builder, baseTypes);
        AppendWhereClauses(builder, typeParameters);

        writer.WriteLine(builder.ToString());
    }

    private static void AppendBaseList(StringBuilder builder, EquatableArray<TypeRef> baseTypes)
    {
        for (var i = 0; i < baseTypes.Count; i++)
        {
            builder.Append(i == 0 ? " : " : ", ").Append(baseTypes[i].FullyQualifiedName);
        }
    }

    private static string KindKeyword(TypeDeclarationKind kind)
    {
        return kind switch
        {
            TypeDeclarationKind.Class => "class",
            TypeDeclarationKind.RecordClass => "record",
            TypeDeclarationKind.Struct => "struct",
            TypeDeclarationKind.RecordStruct => "record struct",
            TypeDeclarationKind.Interface => "interface",
            TypeDeclarationKind.Union => "union",
            _ => throw new ArgumentOutOfRangeException(nameof(kind), kind, "Unsupported type declaration kind."),
        };
    }

    private static void AppendAccessibility(StringBuilder builder, Accessibility accessibility)
    {
        switch (accessibility)
        {
            case Accessibility.Public:
                builder.Append("public ");
                break;
            case Accessibility.Internal:
                builder.Append("internal ");
                break;
            case Accessibility.Private:
                builder.Append("private ");
                break;
            case Accessibility.Protected:
                builder.Append("protected ");
                break;
            case Accessibility.ProtectedOrInternal:
                builder.Append("protected internal ");
                break;
            case Accessibility.ProtectedAndInternal:
                builder.Append("private protected ");
                break;
            case Accessibility.NotApplicable:
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(accessibility), accessibility, "Unsupported accessibility.");
        }
    }

    private static void AppendReturnRefKind(StringBuilder builder, ReturnRefKind kind)
    {
        switch (kind)
        {
            case ReturnRefKind.Ref:
                builder.Append("ref ");
                break;
            case ReturnRefKind.RefReadOnly:
                builder.Append("ref readonly ");
                break;
            case ReturnRefKind.None:
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(kind), kind, "Unsupported return ref kind.");
        }
    }

    private static void AppendScopedKind(StringBuilder builder, ScopedKind scopedKind)
    {
        if (scopedKind is ScopedKind.ScopedRef or ScopedKind.ScopedValue)
        {
            builder.Append("scoped ");
        }
    }

    private static void AppendRefKind(StringBuilder builder, RefKind refKind)
    {
        switch (refKind)
        {
            case RefKind.Ref:
                builder.Append("ref ");
                break;
            case RefKind.Out:
                builder.Append("out ");
                break;
            case RefKind.In:
                builder.Append("in ");
                break;
            case RefKind.RefReadOnlyParameter:
                builder.Append("ref readonly ");
                break;
            case RefKind.None:
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(refKind), refKind, "Unsupported ref kind.");
        }
    }

    private static void AppendParameterList(StringBuilder builder, EquatableArray<ParameterModel> parameters, bool isExtensionMethod)
    {
        builder.Append('(');

        for (var i = 0; i < parameters.Count; i++)
        {
            if (i > 0)
            {
                builder.Append(", ");
            }
            else if (isExtensionMethod)
            {
                builder.Append("this ");
            }

            ParameterModel parameter = parameters[i];

            AppendScopedKind(builder, parameter.ScopedKind);
            AppendRefKind(builder, parameter.RefKind);

            if (parameter.IsParams)
            {
                builder.Append("params ");
            }

            builder.Append(parameter.Type.FullyQualifiedName).Append(' ').Append(parameter.Name);

            if (parameter.DefaultValue is not null)
            {
                builder.Append(" = ").Append(RenderDefaultValue(parameter));
            }
        }

        builder.Append(')');
    }

    private static void AppendTypeParameterList(StringBuilder builder, EquatableArray<TypeParameterModel> typeParameters)
    {
        if (typeParameters.Count == 0)
        {
            return;
        }

        builder.Append('<');

        for (var i = 0; i < typeParameters.Count; i++)
        {
            if (i > 0)
            {
                builder.Append(", ");
            }

            builder.Append(
                typeParameters[i].Variance switch
                {
                    VarianceKind.In => "in ",
                    VarianceKind.Out => "out ",
                    _ => string.Empty,
                });
            builder.Append(typeParameters[i].Name);
        }

        builder.Append('>');
    }

    private static void AppendWhereClauses(StringBuilder builder, EquatableArray<TypeParameterModel> typeParameters)
    {
        for (var i = 0; i < typeParameters.Count; i++)
        {
            TypeParameterModel typeParameter = typeParameters[i];

            if (!HasAnyConstraint(typeParameter))
            {
                continue;
            }

            builder.Append("\n    where ").Append(typeParameter.Name).Append(" : ");
            AppendConstraintList(builder, typeParameter);
        }
    }

    private static bool HasAnyConstraint(TypeParameterModel typeParameter)
    {
        return typeParameter.HasReferenceTypeConstraint
            || typeParameter.HasValueTypeConstraint
            || typeParameter.HasUnmanagedTypeConstraint
            || typeParameter.HasNotNullConstraint
            || typeParameter.HasConstructorConstraint
            || typeParameter.ConstraintTypes.Count > 0;
    }

    // Order matters: class/struct/unmanaged/notnull first, then constraint types, then new() last.
    private static void AppendConstraintList(StringBuilder builder, TypeParameterModel typeParameter)
    {
        var first = true;

        if (typeParameter.HasUnmanagedTypeConstraint)
        {
            builder.Append("unmanaged");
            first = false;
        }
        else if (typeParameter.HasValueTypeConstraint)
        {
            builder.Append("struct");
            first = false;
        }
        else if (typeParameter.HasReferenceTypeConstraint)
        {
            builder.Append("class");

            if (typeParameter.ReferenceTypeConstraintNullableAnnotation == NullableAnnotation.Annotated)
            {
                builder.Append('?');
            }

            first = false;
        }
        else if (typeParameter.HasNotNullConstraint)
        {
            builder.Append("notnull");
            first = false;
        }

        for (var i = 0; i < typeParameter.ConstraintTypes.Count; i++)
        {
            if (!first)
            {
                builder.Append(", ");
            }

            builder.Append(typeParameter.ConstraintTypes[i].FullyQualifiedName);
            first = false;
        }

        if (typeParameter.HasConstructorConstraint)
        {
            if (!first)
            {
                builder.Append(", ");
            }

            builder.Append("new()");
        }
    }

    // Parameter defaults render as `default` rather than `null` when IsDefaultLiteral is set, since
    // ConstantValue.ForNull is shared between an explicit `= null` and `= default` on a value type.
    private static string RenderDefaultValue(ParameterModel parameter)
    {
        return parameter.IsDefaultLiteral ? "default" : RenderConstant(parameter.DefaultValue!);
    }

    // default(T) is the null constant that never trips nullable analysis: `(T)null` warns (CS8600) and
    // `(T?)null` is an error (CS8669) where the consumer has nullable disabled.
    private static string RenderTypedNull(TypeRef type)
    {
        var name = type.FullyQualifiedName;

        if (name.EndsWith("?", StringComparison.Ordinal))
        {
            name = name[..^1];
        }

        return $"default({name})";
    }

    private static string EscapeKeyword(string identifier)
    {
        return SyntaxFacts.GetKeywordKind(identifier) == SyntaxKind.None ? identifier : "@" + identifier;
    }

    // The attribute path is stricter than field and parameter defaults: the argument's type is part of the
    // attribute data and decides overload binding, so small integers, typed nulls and enum members are
    // spelled out instead of relying on a literal's default type.
    private static string RenderConstant(ConstantValue value, bool forAttribute = false)
    {
        return value.Kind switch
        {
            ConstantValueKind.Null => forAttribute && value.Type is not null ? RenderTypedNull(value.Type) : "null",
            ConstantValueKind.String => SymbolDisplay.FormatLiteral((string)value.Value!, quote: true),
            ConstantValueKind.Primitive => forAttribute ? RenderAttributePrimitive(value.Value!) : RenderPrimitive(value.Value!),
            ConstantValueKind.Enum => forAttribute && value.EnumMemberName is not null
                ? $"{value.Type!.FullyQualifiedName}.{EscapeKeyword(value.EnumMemberName)}"
                : RenderEnum(value),
            ConstantValueKind.Type => $"typeof({StripNullableAnnotationForTypeof(value.Type!)})",
            ConstantValueKind.Array => RenderArray(value, forAttribute),
            ConstantValueKind.Error => throw new ArgumentException(
                "Cannot render a constant value of kind Error.",
                nameof(value)),
            _ => throw new ArgumentOutOfRangeException(nameof(value), value.Kind, "Unsupported constant value kind."),
        };
    }

    // A negative underlying value renders as "(global::E)-1", which the compiler parses as a
    // subtraction (the cast-ambiguity rule does not treat '-' as an unambiguous follow token), so
    // the literal is parenthesized to force the cast: "(global::E)(-1)".
    private static string RenderEnum(ConstantValue value)
    {
        var literal = RenderPrimitive(value.Value!);

        if (literal.StartsWith("-", StringComparison.Ordinal))
        {
            literal = $"({literal})";
        }

        return $"({value.Type!.FullyQualifiedName}){literal}";
    }

    private static string RenderPrimitive(object value)
    {
        return value switch
        {
            bool boolValue => boolValue ? "true" : "false",
            char charValue => SymbolDisplay.FormatLiteral(charValue, quote: true),
            float floatValue => RenderFloat(floatValue),
            double doubleValue => RenderDouble(doubleValue),
            decimal decimalValue => decimalValue.ToString(CultureInfo.InvariantCulture) + "m",
            long longValue => longValue.ToString(CultureInfo.InvariantCulture) + "L",
            ulong ulongValue => ulongValue.ToString(CultureInfo.InvariantCulture) + "UL",
            uint uintValue => uintValue.ToString(CultureInfo.InvariantCulture) + "U",
            int or short or ushort or byte or sbyte =>
                Convert.ToInt64(value, CultureInfo.InvariantCulture).ToString(CultureInfo.InvariantCulture),
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Unsupported primitive constant value."),
        };
    }

    // NaN and the infinities have no literal token in C#; the well-known static fields are the
    // only way to express them in source. Finite values round-trip through "G9" (float) / "G17"
    // (double), the exact-round-trip precision for each type.
    private static string RenderFloat(float value)
    {
        if (float.IsNaN(value))
        {
            return "float.NaN";
        }

        if (float.IsPositiveInfinity(value))
        {
            return "float.PositiveInfinity";
        }

        if (float.IsNegativeInfinity(value))
        {
            return "float.NegativeInfinity";
        }

        return value.ToString("G9", CultureInfo.InvariantCulture) + "f";
    }

    private static string RenderDouble(double value)
    {
        if (double.IsNaN(value))
        {
            return "double.NaN";
        }

        if (double.IsPositiveInfinity(value))
        {
            return "double.PositiveInfinity";
        }

        if (double.IsNegativeInfinity(value))
        {
            return "double.NegativeInfinity";
        }

        return value.ToString("G17", CultureInfo.InvariantCulture) + "d";
    }

    private static string RenderAttributePrimitive(object value)
    {
        var literal = RenderPrimitive(value);

        return value switch
        {
            byte => $"(byte){literal}",
            sbyte => $"(sbyte){literal}",
            short => $"(short){literal}",
            ushort => $"(ushort){literal}",
            _ => literal,
        };
    }

    // `new[] { }` does not compile, nor does `new[] { null }` or a mixed `new[] { 1, "a" }`, so the
    // array type is written whenever the model knows it.
    private static string RenderArray(ConstantValue value, bool forAttribute)
    {
        var builder = new StringBuilder();

        if (value.Type is null)
        {
            builder.Append("new[] { ");
        }
        else
        {
            var typeName = value.Type.FullyQualifiedName;

            if (typeName.EndsWith("?", StringComparison.Ordinal))
            {
                typeName = typeName[..^1];
            }

            if (value.Elements.Count == 0)
            {
                return $"new {typeName} {{ }}";
            }

            builder.Append("new ").Append(typeName).Append(" { ");
        }

        for (var i = 0; i < value.Elements.Count; i++)
        {
            if (i > 0)
            {
                builder.Append(", ");
            }

            builder.Append(RenderConstant(value.Elements[i], forAttribute));
        }

        builder.Append(" }");

        return builder.ToString();
    }

    // typeof(string?) is a compile error (CS8639): nullable annotations on a reference type are not
    // permitted in that context, so the trailing '?' is stripped for anything but a value type, where
    // it instead denotes a real Nullable<T> (e.g. typeof(int?) is valid).
    private static string StripNullableAnnotationForTypeof(TypeRef type)
    {
        var name = type.FullyQualifiedName;

        if (!type.IsValueType && name.EndsWith("?", StringComparison.Ordinal))
        {
            name = name[..^1];
        }

        return name;
    }

    /// <summary>
    /// Closes every block a <see cref="WriteTypeDeclaration"/> call opened, innermost first, when
    /// disposed. Disposing a default instance or disposing twice is a no-op.
    /// </summary>
    internal struct TypeDeclarationScope : IDisposable
    {
        private SourceWriter.BlockScope[]? _scopes;

        internal TypeDeclarationScope(SourceWriter.BlockScope[] scopes)
        {
            _scopes = scopes;
        }

        public void Dispose()
        {
            if (_scopes is null)
            {
                return;
            }

            for (var i = _scopes.Length - 1; i >= 0; i--)
            {
                _scopes[i].Dispose();
            }

            _scopes = null;
        }
    }
}
